#include "EmberLifetime.h"
bool EmberValidateLifetime(const TSharedPtr<FJsonObject>& Effect,FString& Error){
 if(!Effect->HasField(TEXT("lifetime")))return true;const TSharedPtr<FJsonObject>* Curves=nullptr;if(!Effect->TryGetObjectField(TEXT("lifetime"),Curves)){Error=TEXT("Invalid lifetime curves");return false;}
 for(const auto& Pair:(*Curves)->Values){const FString Key(*Pair.Key);const TArray<TSharedPtr<FJsonValue>>* Points=nullptr;if(!TArray<FString>{TEXT("size"),TEXT("opacity"),TEXT("color"),TEXT("glow")}.Contains(Key)||!Pair.Value->TryGetArray(Points)||Points->Num()<2||Points->Num()>8){Error=TEXT("Invalid lifetime curve");return false;}double Previous=-1;for(int32 I=0;I<Points->Num();I++){const TSharedPtr<FJsonObject>* Point=nullptr;double Time;if(!(*Points)[I]->TryGetObject(Point)||!(*Point)->TryGetNumberField(TEXT("time"),Time)||!FMath::IsFinite(Time)||Time<0||Time>1||Time<=Previous||(I==0&&Time!=0)||(I==Points->Num()-1&&Time!=1)){Error=TEXT("Invalid lifetime stop age");return false;}Previous=Time;if(Key==TEXT("color")){FString Value;if(!(*Point)->TryGetStringField(TEXT("value"),Value)||Value.Len()!=7||Value[0]!='#'){Error=TEXT("Invalid gradient color");return false;}for(int32 C=1;C<7;C++)if(!FChar::IsHexDigit(Value[C])){Error=TEXT("Invalid gradient color");return false;}}else{double Value;if(!(*Point)->TryGetNumberField(TEXT("value"),Value)||!FMath::IsFinite(Value)||Value<0||Value>(Key==TEXT("size")?5:1)){Error=TEXT("Invalid lifetime stop value");return false;}}}}
 return true;
}
FString EmberLifetimeValue(const TSharedPtr<FJsonObject>& Effect,const TCHAR* Property,const FString& Fallback){
 const TSharedPtr<FJsonObject>* Curves=nullptr;const TArray<TSharedPtr<FJsonValue>>* Points=nullptr;if(!Effect->TryGetObjectField(TEXT("lifetime"),Curves)||!(*Curves)->TryGetArrayField(Property,Points))return Fallback;
 auto Value=[&](int32 I){auto Point=(*Points)[I]->AsObject();if(FString(Property)==TEXT("color")){const FLinearColor Color=FLinearColor::FromSRGBColor(FColor::FromHex(Point->GetStringField(TEXT("value"))));return FString::Printf(TEXT("float3(%s,%s,%s)"),*FString::SanitizeFloat(Color.R),*FString::SanitizeFloat(Color.G),*FString::SanitizeFloat(Color.B));}return FString::SanitizeFloat(Point->GetNumberField(TEXT("value")));};
 FString Expression=Value(Points->Num()-1);for(int32 I=Points->Num()-2;I>=0;I--){double A=(*Points)[I]->AsObject()->GetNumberField(TEXT("time")),B=(*Points)[I+1]->AsObject()->GetNumberField(TEXT("time"));Expression=FString::Printf(TEXT("(t<=%s?lerp(%s,%s,saturate((t-%s)/%s)):%s)"),*FString::SanitizeFloat(B),*Value(I),*Value(I+1),*FString::SanitizeFloat(A),*FString::SanitizeFloat(B-A),*Expression);}return Expression;
}
